import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Ensure amount is not zero to have a meaningful balance change scenario
        amount = bound(amount, 1, 1e18);

        // Fund the contract
        address(c).call{value: amount}("");
        uint256 balanceBefore = address(c).balance;

        // Call forward with a non-contract address (will always fail)
        c.forward(address(1), "");

        // Assert that balance did not decrease (which would happen if the call succeeded and transferred funds out)
        assertTrue(address(c).balance >= balanceBefore);
    }
}

