pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        // Ensure the call will revert by targeting a non-existent contract or reverting receiver
        vm.assume(callee != address(0));
        // Deploy a simple contract that always reverts
        address revertTarget = address(new Reverter());

        uint256 balanceBefore = address(c).balance;
        // This call to forward should always revert in the reference contract
        // because the target always reverts. In the mutant, it does nothing and returns.
        try c.forward(revertTarget, _data) {
            // If no revert, the mutant was used
            // In reference, this path should never be reached
            revert("unexpected success");
        } catch {
            // Expected revert in reference
        }
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceBefore == balanceAfter, "Balance changed");
    }
}

contract Reverter {
    fallback() external payable { revert("always revert"); }
}

